  "modal.aniversarioTitulo": "Parabéns!",
  "modal.aniversarioTituloNome": "Parabéns, {nome}!",
  "modal.aniversarioTexto": "Hoje é o teu dia, e nós cá da Ippon League queremos celebrá-lo contigo! 🥋 Estamos muito felizes por fazeres parte desta comunidade de apaixonados pelo judô. Que este novo ano te traga muitas alegrias, conquistas no tatame e fora dele — e que continues a crescer e a divertir-te connosco. Um grande abraço, e parabéns! 🎂",
  "modal.aniversarioBotao": "Obrigado! 🙏",
  "modal.diaDoJudoTitulo": "Dia Mundial do Judô",
  "modal.diaDoJudoTexto": "Hoje é o Dia Mundial do Judô! Parabéns a todos os que amam este desporto. Que tal homenagear a data com uma escalação de respeito?",
  "modal.diaDoJudoTextoNome": "{nome}, hoje é o Dia Mundial do Judô! Parabéns a todos os que amam este desporto. Que tal homenagear a data com uma escalação de respeito?",
  "modal.diaDoJudoBotao": "Bora homenagear! 🥋",
  "modal.olimpiadaTitulo": "É tempo de Jogos Olímpicos!",
  "modal.olimpiadaTexto": "O maior palco do desporto mundial abriu as portas ao judô! 🏅 Só os melhores entre os melhores chegam aqui — os medalhistas olímpicos entram para a história. É o sonho de todo o judoca, e tu vais viver isto connosco. Prepara a tua equipa dos sonhos e entra nesta rodada histórica!",
  "modal.olimpiadaBotao": "Vamos a isto! 🔥",
  "modal.mundialTitulo": "É a semana do Mundial!",
  "modal.mundialTexto": "Atenção, atleta: chegou a competição mais importante do ano! 🌍 O Mundial de Judô reúne os melhores do planeta no mesmo tatame — é aqui que se consagram os campeões do mundo de {ano}. Uma rodada destas não se repete. Monta a tua melhor equipa, escolhe bem o capitão e não percas esta!",
  "modal.mundialBotao": "Bora escalar! 🥋",
  "modal.mastersTitulo": "É a semana do Masters!",
  "modal.mastersTexto": "O Masters é só para a elite: entram apenas os melhores do ranking mundial de cada categoria. 🏆 Cada luta é entre feras — pontos não vão faltar para quem escalar com sabedoria. Esta é uma rodada de respeito. Escolhe a dedo o teu time e mostra o que vales!",
  "modal.mastersBotao": "Montar o meu time! 🥋",
  "modal.contEURTitulo": "É a semana do Campeonato da Europa!",
  "modal.contEURTexto": "O título continental está em jogo, e é no teu continente! 🇪🇺 Os melhores da Europa vão medir forças — uma grande oportunidade para fazeres pontos e subires na tua liga continental. Não deixes passar a tua rodada!",
  "modal.contPANTitulo": "É a semana do Campeonato Pan-Americano!",
  "modal.contPANTexto": "O título continental está em jogo, e é no teu continente! 🌎 Os melhores da América vão à luta — aproveita para fazer pontos e brilhar na tua liga continental. A tua rodada é agora!",
  "modal.contASITitulo": "É a semana do Campeonato Asiático!",
  "modal.contASITexto": "O título continental está em jogo, e é no teu continente! 🌏 Os melhores da Ásia entram no tatame — uma grande oportunidade para pontuares e subires na tua liga continental. Não percas a tua rodada!",
  "modal.contAFRTitulo": "É a semana do Campeonato Africano!",
  "modal.contAFRTexto": "O título continental está em jogo, e é no teu continente! 🌍 Os melhores de África vão medir forças — aproveita para fazer pontos e brilhar na tua liga continental. A tua rodada chegou!",
  "modal.contOCETitulo": "É a semana do Campeonato da Oceânia!",
  "modal.contOCETexto": "O título continental está em jogo, e é no teu continente! 🌏 Os melhores da Oceânia entram em ação — uma boa altura para pontuares e subires na tua liga continental. Não deixes escapar a tua rodada!",
  "modal.continentalBotao": "Bora competir! 🥋",
  "modal.fimAnoTitulo": "Boas festas, atleta!",
  "modal.fimAnoTexto": "Obrigado por fazeres parte da Ippon League em {ano}. Que {anoSeguinte} traga muitos ippons. 🥋",
  "modal.fimAnoBotao": "Boas festas! 🎄",
  "modal.comecoAnoTitulo": "Época nova, tatame limpo!",
  "modal.comecoAnoTexto": "O ranking recomeça do zero — todos com as mesmas hipóteses. Monta a tua equipa e começa o ano a pontuar.",
  "modal.comecoAnoBotao": "Começar a pontuar! 🥋",
