  // --- sobre-pro (acrescentado) ---
  "pro.sobreTitulo": "Pro and Pro Max",
  "pro.sobreIntro": "Two levels of edge to play with more information. %P% gives you the scout and analysis tools; %M% adds live competition and more. The strategy is always yours.",
  "pro.sobreQueTens": "What you get with Pro",
  "pro.vaScoutT": "Advanced scouting",
  "pro.vaScoutD": "Stats based on each athlete's real history: titles, recent form and how they score at each competition level.",
  "pro.vaTimeT": "Analysis of your team",
  "pro.vaTimeD": "An honest read of your lineup: what looks solid, where the risk is and why. Without telling you what to do — the decision is always yours.",
  "pro.vaCapitaoT": "Captain tip",
  "pro.vaCapitaoD": "Among the athletes you picked, which one has the strongest history for this competition. You still build your team your way.",
  "pro.vaValorizacaoT": "Greater chance of value growth",
  "pro.vaValorizacaoD": "From the history analysis, see which of your athletes are most likely to grow in value and yield JC. It's a trend, not a guarantee.",
  "pro.vaChaveamentoT": "Competition brackets",
  "pro.vaChaveamentoD": "See each competition's fight bracket and follow your athletes' path through it.",
  "pro.vaAoVivoT": "Live tracking",
  "pro.vaAoVivoD": "On competition day, track your athletes' scores in real time.",
  "pro.va5LigasT": "Up to 5 active leagues",
  "pro.va5LigasD": "Create up to 5 leagues at once, between knockout and round-robin.",
  "pro.vaDesignT": "Exclusive Pro design",
  "pro.vaDesignD": "A distinct look of its own, only for Ippon Pro members.",
  "pro.sobreMaxAcrescenta": "Pro Max adds",
  "pro.sobreMaxInclui": "Pro Max includes %D% — and also:",
  "pro.sobreMaxIncluiDestaque": "everything Pro has",
  "pro.sobreNaoFaz": "What Pro doesn't do",
  "pro.sobreNaoFazCorpo": "Pro %A% and %B%. We don't hand over “the best of the round” or who to bet on — that would take the fun out of the game. We give you information and readings of the history; the credit for getting it right is always yours.",
  "pro.sobreNaoFazA": "doesn't build your team for you",
  "pro.sobreNaoFazB": "doesn't tell you who's going to win the competition",
  "pro.sobreAssinatura": "The subscription",
  "pro.sobre7diasD": "Try Pro for 7 days. If you cancel within that period, you pay nothing.",
  "pro.sobreMensalT": "Monthly plan",
  "pro.sobreMensalD": "The subscription is monthly and renews automatically every month, until you cancel. If you cancel, you keep access until the end of the month already paid.",
  "pro.sobreCancelarT": "Cancel anytime",
  "pro.sobreCancelarD": "When you cancel, you keep access until the end of the period already paid — there's just no new renewal.",
  "pro.sobreTransparencia": "Full transparency",
  "pro.sobreTransp1": "We want to be very clear with you about what Pro is — and what it isn't.",
  "pro.sobreTransp2": "Ippon Pro offers %D%, based on data and the athletes' history: their results in recent competitions and how they usually score at each level. We show trends and possibilities — for example, who's most likely to grow in value.",
  "pro.sobreTransp2Destaque": "information only",
  "pro.sobreTransp3": "By subscribing, you acknowledge that Pro is %D%. We never promise certainties or tell you who to bet on. The decision and the strategy are always yours.",
  "pro.sobreTransp3Destaque": "merely informative and guarantees no result",
  "pro.sobreVerPro": "See Ippon Pro",
  "pro.sobreEsMembro": "You're an Ippon Pro member. Thanks for being part of it!",

