  "modal.olimpiadaTitulo": "It's time for the Olympic Games!",
  "modal.olimpiadaTexto": "The biggest stage in world sport has opened its doors to judo! 🏅 Only the best of the best make it here — Olympic medalists go down in history. It's every judoka's dream, and you'll live it with us. Prepare your dream team and step into this historic round!",
  "modal.olimpiadaBotao": "Let's do this! 🔥",
  "modal.mundialTitulo": "It's World Championship week!",
  "modal.mundialTexto": "Heads up, athlete: the most important competition of the year is here! 🌍 The Judo World Championships bring the planet's best onto the same tatame — this is where the {ano} world champions are crowned. A round like this doesn't come around twice. Build your best team, pick your captain wisely and don't miss it!",
  "modal.mundialBotao": "Let's line up! 🥋",
  "modal.mastersTitulo": "It's Masters week!",
  "modal.mastersTexto": "The Masters is elite only: just the top of the world ranking in each category get in. 🏆 Every bout is between beasts — points won't be lacking for anyone who lines up wisely. This is a round to respect. Hand-pick your team and show what you're worth!",
  "modal.mastersBotao": "Build my team! 🥋",
  "modal.contEURTitulo": "It's European Championship week!",
  "modal.contEURTexto": "The continental title is up for grabs, and it's on your continent! 🇪🇺 Europe's best will go head to head — a great chance to score points and climb your continental league. Don't let your round slip by!",
  "modal.contPANTitulo": "It's Pan American Championship week!",
  "modal.contPANTexto": "The continental title is up for grabs, and it's on your continent! 🌎 The Americas' best step into the fight — take the chance to score points and shine in your continental league. Your round is now!",
  "modal.contASITitulo": "It's Asian Championship week!",
  "modal.contASITexto": "The continental title is up for grabs, and it's on your continent! 🌏 Asia's best step onto the tatame — a great chance to score and climb your continental league. Don't miss your round!",
  "modal.contAFRTitulo": "It's African Championship week!",
  "modal.contAFRTexto": "The continental title is up for grabs, and it's on your continent! 🌍 Africa's best go head to head — take the chance to score points and shine in your continental league. Your round has arrived!",
  "modal.contOCETitulo": "It's Oceania Championship week!",
