  "pro.sobreTitulo": "Pro y Pro Max",
  "pro.sobreIntro": "Dos niveles de ventaja para jugar con más información. %P% te da las herramientas de scout y análisis; %M% añade la competición en vivo y más. La estrategia siempre es tuya.",
  "pro.sobreQueTens": "Lo que tienes con Pro",
  "pro.vaScoutT": "Scout avanzado",
  "pro.vaScoutD": "Estadísticas basadas en el historial real de cada atleta: títulos, forma reciente y cómo puntúa en cada nivel de competición.",
  "pro.vaTimeT": "Análisis de tu equipo",
  "pro.vaTimeD": "Una lectura honesta de tu alineación: qué parece sólido, dónde hay riesgo y por qué. Sin decirte qué hacer — la decisión siempre es tuya.",
  "pro.vaCapitaoT": "Consejo de capitán",
  "pro.vaCapitaoD": "Entre los atletas que elegiste, cuál tiene el historial más fuerte para esta competición. Sigues armando tu equipo a tu manera.",
  "pro.vaValorizacaoT": "Mayor posibilidad de revalorización",
  "pro.vaValorizacaoD": "Por el análisis del historial, ve cuáles de tus atletas tienen más opciones de revalorizarse y rendir JC. Es una tendencia, no una garantía.",
  "pro.vaChaveamentoT": "Cuadros de las competiciones",
  "pro.vaChaveamentoD": "Ve el cuadro de combates de cada competición y sigue el camino de tus atletas en el cuadro.",
  "pro.vaAoVivoT": "Seguimiento en vivo",
  "pro.vaAoVivoD": "El día de la competición, sigue las puntuaciones de tus atletas en tiempo real.",
  "pro.va5LigasT": "Hasta 5 ligas activas",
  "pro.va5LigasD": "Crea hasta 5 ligas a la vez, entre mata-mata y liga regular.",
  "pro.vaDesignT": "Diseño exclusivo Pro",
  "pro.vaDesignD": "Un aspecto propio y distinto, solo para miembros Ippon Pro.",
  "pro.sobreMaxAcrescenta": "Pro Max añade",
  "pro.sobreMaxInclui": "Pro Max incluye %D% — y además:",
  "pro.sobreMaxIncluiDestaque": "todo lo que tiene Pro",
  "pro.sobreNaoFaz": "Lo que Pro no hace",
  "pro.sobreNaoFazCorpo": "Pro %A% y %B%. No entregamos «los mejores de la rodada» ni en quién apostar — eso quitaría la gracia del juego. Te damos información y lecturas del historial; el mérito de acertar es siempre tuyo.",
