  "pro.sobreCancelarT": "Cancela cuando quieras",
  "pro.sobreCancelarD": "Al cancelar, mantienes el acceso hasta el final del período ya pagado — solo no hay nueva renovación.",
  "pro.sobreTransparencia": "Transparencia total",
  "pro.sobreTransp1": "Queremos ser muy claros contigo sobre lo que Pro es — y lo que no es.",
  "pro.sobreTransp2": "Ippon Pro ofrece %D%, basada en datos y en el historial de los atletas: sus resultados en las últimas competiciones y cómo suelen puntuar en cada nivel. Mostramos tendencias y posibilidades — por ejemplo, quién tiene más opciones de revalorizarse.",
  "pro.sobreTransp2Destaque": "solo información",
