  "modal.aniversarioTitulo": "¡Feliz cumpleaños!",
  "modal.aniversarioTituloNome": "¡Feliz cumpleaños, {nome}!",
  "modal.aniversarioTexto": "¡Hoy es tu día, y en la Ippon League queremos celebrarlo contigo! 🥋 Estamos muy felices de que formes parte de esta comunidad de apasionados por el judo. Que este nuevo año te traiga muchas alegrías, logros en el tatame y fuera de él — y que sigas creciendo y divirtiéndote con nosotros. ¡Un fuerte abrazo y feliz cumpleaños! 🎂",
  "modal.aniversarioBotao": "¡Gracias! 🙏",
  "modal.diaDoJudoTitulo": "Día Mundial del Judo",
  "modal.diaDoJudoTexto": "¡Hoy es el Día Mundial del Judo! Enhorabuena a todos los que aman este deporte. ¿Qué tal homenajear la fecha con una alineación de respeto?",
  "modal.diaDoJudoTextoNome": "{nome}, ¡hoy es el Día Mundial del Judo! Enhorabuena a todos los que aman este deporte. ¿Qué tal homenajear la fecha con una alineación de respeto?",
  "modal.diaDoJudoBotao": "¡A homenajear! 🥋",
  "modal.olimpiadaTitulo": "¡Es tiempo de Juegos Olímpicos!",
  "modal.olimpiadaTexto": "¡El mayor escenario del deporte mundial le abrió las puertas al judo! 🏅 Solo los mejores entre los mejores llegan aquí — los medallistas olímpicos entran en la historia. Es el sueño de todo judoka, y lo vivirás con nosotros. ¡Prepara tu equipo de ensueño y entra en esta ronda histórica!",
  "modal.olimpiadaBotao": "¡Vamos a ello! 🔥",
  "modal.mundialTitulo": "¡Es la semana del Mundial!",
  "modal.mundialTexto": "¡Atención, atleta: llegó la competición más importante del año! 🌍 El Mundial de Judo reúne a los mejores del planeta en el mismo tatame — aquí es donde se coronan los campeones del mundo de {ano}. Una ronda así no se repite. Monta tu mejor equipo, elige bien al capitán y ¡no te la pierdas!",
  "modal.mundialBotao": "¡A alinear! 🥋",
  "modal.mastersTitulo": "¡Es la semana del Masters!",
  "modal.mastersTexto": "El Masters es solo para la élite: entran únicamente los mejores del ranking mundial de cada categoría. 🏆 Cada combate es entre fieras — no faltarán puntos para quien alinee con cabeza. Esta es una ronda de respeto. Elige a dedo tu equipo y ¡demuestra lo que vales!",
  "modal.mastersBotao": "¡A montar mi equipo! 🥋",
  "modal.contEURTitulo": "¡Es la semana del Campeonato de Europa!",
  "modal.contEURTexto": "¡El título continental está en juego, y es en tu continente! 🇪🇺 Los mejores de Europa van a medir fuerzas — una gran oportunidad para hacer puntos y subir en tu liga continental. ¡No dejes pasar tu ronda!",
  "modal.contPANTitulo": "¡Es la semana del Campeonato Panamericano!",
  "modal.contPANTexto": "¡El título continental está en juego, y es en tu continente! 🌎 Los mejores de América van a la lucha — aprovecha para hacer puntos y brillar en tu liga continental. ¡Tu ronda es ahora!",
  "modal.contASITitulo": "¡Es la semana del Campeonato Asiático!",
  "modal.contASITexto": "¡El título continental está en juego, y es en tu continente! 🌏 Los mejores de Asia entran en el tatame — una gran oportunidad para puntuar y subir en tu liga continental. ¡No te pierdas tu ronda!",
  "modal.contAFRTitulo": "¡Es la semana del Campeonato Africano!",
