  // --- sobre-pro (acrescentado) ---
  "pro.sobreTitulo": "Pro et Pro Max",
  "pro.sobreIntro": "Deux niveaux d'avantage pour jouer avec plus d'informations. %P% te donne les outils de scouting et d'analyse ; %M% ajoute la compétition en direct et plus. La stratégie reste toujours la tienne.",
  "pro.sobreQueTens": "Ce que tu as avec Pro",
  "pro.vaScoutT": "Scouting avancé",
  "pro.vaScoutD": "Des statistiques basées sur l'historique réel de chaque athlète : titres, forme récente et façon de marquer à chaque niveau de compétition.",
  "pro.vaTimeT": "Analyse de ton équipe",
  "pro.vaTimeD": "Une lecture honnête de ta composition : ce qui semble solide, où se situe le risque et pourquoi. Sans te dire quoi faire — la décision reste la tienne.",
  "pro.vaCapitaoT": "Conseil de capitaine",
  "pro.vaCapitaoD": "Parmi les athlètes que tu as choisis, celui qui a l'historique le plus solide pour cette compétition. Tu continues de monter ton équipe à ta façon.",
  "pro.vaValorizacaoT": "Plus de chances de valorisation",
  "pro.vaValorizacaoD": "Grâce à l'analyse de l'historique, vois lesquels de tes athlètes ont le plus de chances de prendre de la valeur et de rapporter des JC. C'est une tendance, pas une garantie.",
  "pro.vaChaveamentoT": "Tableaux des compétitions",
  "pro.vaChaveamentoD": "Vois le tableau des combats de chaque compétition et suis le parcours de tes athlètes.",
  "pro.vaAoVivoT": "Suivi en direct",
  "pro.vaAoVivoD": "Le jour de la compétition, suis les scores de tes athlètes en temps réel.",
  "pro.va5LigasT": "Jusqu'à 5 ligues actives",
  "pro.va5LigasD": "Crée jusqu'à 5 ligues à la fois, entre élimination et championnat.",
  "pro.vaDesignT": "Design exclusif Pro",
  "pro.vaDesignD": "Un visuel qui lui est propre, réservé aux membres Ippon Pro.",
  "pro.sobreMaxAcrescenta": "Pro Max ajoute",
  "pro.sobreMaxInclui": "Pro Max inclut %D% — et en plus :",
  "pro.sobreMaxIncluiDestaque": "tout ce qu'a Pro",
  "pro.sobreNaoFaz": "Ce que Pro ne fait pas",
  "pro.sobreNaoFazCorpo": "Pro %A% et %B%. On ne livre pas « les meilleurs de la journée » ni sur qui parier — cela gâcherait le plaisir du jeu. On te donne des informations et des lectures de l'historique ; le mérite de voir juste reste le tien.",
  "pro.sobreNaoFazA": "ne monte pas ton équipe à ta place",
  "pro.sobreNaoFazB": "ne te dit pas qui va gagner la compétition",
  "pro.sobreAssinatura": "L'abonnement",
  "pro.sobre7diasD": "Essaie Pro pendant 7 jours. Si tu résilies durant cette période, tu ne paies rien.",
  "pro.sobreMensalT": "Formule mensuelle",
  "pro.sobreMensalD": "L'abonnement est mensuel et se renouvelle automatiquement chaque mois, jusqu'à résiliation. Si tu résilies, tu gardes l'accès jusqu'à la fin du mois déjà payé.",
  "pro.sobreCancelarT": "Résilie quand tu veux",
  "pro.sobreCancelarD": "En résiliant, tu gardes l'accès jusqu'à la fin de la période déjà payée — il n'y a simplement pas de nouveau renouvellement.",
  "pro.sobreTransparencia": "Transparence totale",
  "pro.sobreTransp1": "On veut être très clairs avec toi sur ce qu'est Pro — et ce qu'il n'est pas.",
  "pro.sobreTransp2": "Ippon Pro offre %D%, basée sur les données et l'historique des athlètes : leurs résultats dans les dernières compétitions et leur façon de marquer à chaque niveau. On montre des tendances et des possibilités — par exemple, qui a le plus de chances de prendre de la valeur.",
  "pro.sobreTransp2Destaque": "uniquement de l'information",
  "pro.sobreTransp3": "En t'abonnant, tu reconnais que Pro est %D%. On ne promet jamais de certitudes ni ne te dit sur qui parier. La décision et la stratégie restent toujours les tiennes.",
  "pro.sobreTransp3Destaque": "purement informatif et ne garantit aucun résultat",
  "pro.sobreVerPro": "Voir Ippon Pro",
  "pro.sobreEsMembro": "Tu es membre Ippon Pro. Merci d'en faire partie !",

