  "ajuda.mensagemEnviadaCorpo": "Nous avons reçu ton message. Si tu as laissé un e-mail, nous répondrons par là. Merci d'aider Ippon League à s'améliorer.",
  "ajuda.voltarInicio": "Retour à l'accueil",
  "ajuda.intro": "Question, problème, suggestion ou juste un compliment ? Écris-nous — nous répondons à l'e-mail de ton compte.",
