  "modal.aniversarioTitulo": "Joyeux anniversaire !",
  "modal.aniversarioTituloNome": "Joyeux anniversaire, {nome} !",
  "modal.aniversarioTexto": "Aujourd'hui, c'est ton jour, et toute l'équipe de l'Ippon League veut le célébrer avec toi ! 🥋 Nous sommes très heureux que tu fasses partie de cette communauté de passionnés de judo. Que cette nouvelle année t'apporte plein de joies, des victoires sur le tatame et en dehors — et que tu continues à grandir et à t'amuser avec nous. Une grosse accolade, et joyeux anniversaire ! 🎂",
  "modal.aniversarioBotao": "Merci ! 🙏",
  "modal.diaDoJudoTitulo": "Journée mondiale du judo",
  "modal.diaDoJudoTexto": "Aujourd'hui, c'est la Journée mondiale du judo ! Félicitations à tous ceux qui aiment ce sport. Et si tu rendais hommage à cette date avec une composition de respect ?",
  "modal.diaDoJudoTextoNome": "{nome}, aujourd'hui c'est la Journée mondiale du judo ! Félicitations à tous ceux qui aiment ce sport. Et si tu rendais hommage à cette date avec une composition de respect ?",
  "modal.diaDoJudoBotao": "Rendons hommage ! 🥋",
  "modal.olimpiadaTitulo": "C'est l'heure des Jeux Olympiques !",
  "modal.olimpiadaTexto": "La plus grande scène du sport mondial a ouvert ses portes au judo ! 🏅 Seuls les meilleurs des meilleurs arrivent ici — les médaillés olympiques entrent dans l'histoire. C'est le rêve de tout judoka, et tu vas le vivre avec nous. Prépare ton équipe de rêve et entre dans cette journée historique !",
  "modal.olimpiadaBotao": "On y va ! 🔥",
  "modal.mundialTitulo": "C'est la semaine des Championnats du monde !",
  "modal.mundialTexto": "Attention, athlète : la compétition la plus importante de l'année est arrivée ! 🌍 Les Championnats du monde de judo réunissent les meilleurs de la planète sur le même tatame — c'est ici que sont sacrés les champions du monde {ano}. Une journée comme celle-ci ne se répète pas. Constitue ta meilleure équipe, choisis bien ton capitaine et ne la manque pas !",
  "modal.mundialBotao": "Allons aligner ! 🥋",
  "modal.mastersTitulo": "C'est la semaine du Masters !",
  "modal.mastersTexto": "Le Masters, c'est l'élite uniquement : seuls les meilleurs du classement mondial de chaque catégorie y entrent. 🏆 Chaque combat oppose des bêtes — les points ne manqueront pas à qui aligne avec sagesse. C'est une journée de respect. Choisis ton équipe avec soin et montre ce que tu vaux !",
  "modal.mastersBotao": "Constituer mon équipe ! 🥋",
  "modal.contEURTitulo": "C'est la semaine du Championnat d'Europe !",
  "modal.contEURTexto": "Le titre continental est en jeu, et c'est sur ton continent ! 🇪🇺 Les meilleurs d'Europe vont s'affronter — une belle occasion de marquer des points et de grimper dans ta ligue continentale. Ne laisse pas passer ta journée !",
  "modal.contPANTitulo": "C'est la semaine du Championnat panaméricain !",
