  // --- sobre-pro (acrescentado) ---
  "pro.sobreTitulo": "Pro und Pro Max",
  "pro.sobreIntro": "Zwei Stufen des Vorteils, um mit mehr Informationen zu spielen. %P% gibt dir die Scout- und Analyse-Tools; %M% ergänzt den Live-Wettkampf und mehr. Die Strategie bleibt immer deine.",
  "pro.sobreQueTens": "Was du mit Pro bekommst",
  "pro.vaScoutT": "Erweitertes Scouting",
  "pro.vaScoutD": "Statistiken auf Basis der echten Historie jedes Athleten: Titel, aktuelle Form und wie er auf jeder Wettkampfebene punktet.",
  "pro.vaTimeT": "Analyse deines Teams",
  "pro.vaTimeD": "Eine ehrliche Einschätzung deiner Aufstellung: was solide wirkt, wo das Risiko liegt und warum. Ohne dir zu sagen, was zu tun ist — die Entscheidung bleibt deine.",
  "pro.vaCapitaoT": "Kapitän-Tipp",
  "pro.vaCapitaoD": "Unter den von dir gewählten Athleten der mit der stärksten Historie für diesen Wettkampf. Du stellst dein Team weiter auf deine Weise auf.",
  "pro.vaValorizacaoT": "Größere Chance auf Wertsteigerung",
  "pro.vaValorizacaoD": "Aus der Historien-Analyse siehst du, welche deiner Athleten am ehesten an Wert gewinnen und JC bringen. Das ist eine Tendenz, keine Garantie.",
  "pro.vaChaveamentoT": "Turnierbäume der Wettkämpfe",
  "pro.vaChaveamentoD": "Sieh den Kampfbaum jedes Wettkampfs und verfolge den Weg deiner Athleten darin.",
  "pro.vaAoVivoT": "Live-Verfolgung",
  "pro.vaAoVivoD": "Am Wettkampftag verfolgst du die Punkte deiner Athleten in Echtzeit.",
  "pro.va5LigasT": "Bis zu 5 aktive Ligen",
  "pro.va5LigasD": "Erstelle bis zu 5 Ligen gleichzeitig, zwischen K.-o. und Punktrunde.",
  "pro.vaDesignT": "Exklusives Pro-Design",
  "pro.vaDesignD": "Ein eigenes, unverwechselbares Design, nur für Ippon-Pro-Mitglieder.",
  "pro.sobreMaxAcrescenta": "Pro Max ergänzt",
  "pro.sobreMaxInclui": "Pro Max enthält %D% — und außerdem:",
  "pro.sobreMaxIncluiDestaque": "alles, was Pro hat",
  "pro.sobreNaoFaz": "Was Pro nicht tut",
  "pro.sobreNaoFazCorpo": "Pro %A% und %B%. Wir liefern nicht „die Besten der Runde“ oder auf wen du setzen sollst — das würde den Spaß am Spiel nehmen. Wir geben dir Informationen und Auswertungen der Historie; das Verdienst, richtig zu liegen, bleibt deins.",
  "pro.sobreNaoFazA": "stellt dein Team nicht für dich auf",
  "pro.sobreNaoFazB": "sagt dir nicht, wer den Wettkampf gewinnt",
  "pro.sobreAssinatura": "Das Abo",
  "pro.sobre7diasD": "Teste Pro 7 Tage lang. Wenn du in diesem Zeitraum kündigst, zahlst du nichts.",
  "pro.sobreMensalT": "Monatsplan",
  "pro.sobreMensalD": "Das Abo ist monatlich und verlängert sich automatisch jeden Monat, bis du kündigst. Wenn du kündigst, behältst du den Zugang bis zum Ende des bereits bezahlten Monats.",
  "pro.sobreCancelarT": "Jederzeit kündbar",
  "pro.sobreCancelarD": "Beim Kündigen behältst du den Zugang bis zum Ende des bereits bezahlten Zeitraums — es gibt nur keine neue Verlängerung.",
  "pro.sobreTransparencia": "Volle Transparenz",
  "pro.sobreTransp1": "Wir wollen dir gegenüber sehr klar sein, was Pro ist — und was nicht.",
  "pro.sobreTransp2": "Ippon Pro bietet %D%, basierend auf Daten und der Historie der Athleten: ihre Ergebnisse in den letzten Wettkämpfen und wie sie üblicherweise auf jeder Ebene punkten. Wir zeigen Tendenzen und Möglichkeiten — zum Beispiel, wer am ehesten an Wert gewinnt.",
  "pro.sobreTransp2Destaque": "nur Informationen",
  "pro.sobreTransp3": "Mit dem Abo erkennst du an: Pro ist %D%. Wir versprechen nie Gewissheiten und sagen dir nicht, auf wen du setzen sollst. Entscheidung und Strategie bleiben immer deine.",
  "pro.sobreTransp3Destaque": "rein informativ und garantiert kein Ergebnis",
  "pro.sobreVerPro": "Ippon Pro ansehen",
  "pro.sobreEsMembro": "Du bist Ippon-Pro-Mitglied. Danke, dass du dabei bist!",

