  "ajuda.asParcerias": "Partnerschaften",
  "ajuda.asOutro": "Sonstiges",
  "ajuda.mensagemEnviadaTit": "Nachricht gesendet",
  "ajuda.mensagemEnviadaCorpo": "Wir haben deine Nachricht erhalten. Wenn du eine E-Mail hinterlassen hast, antworten wir dort. Danke, dass du hilfst, Ippon League besser zu machen.",
  "ajuda.voltarInicio": "Zurück zum Start",
  "ajuda.intro": "Frage, Problem, Vorschlag oder einfach ein Lob? Schreib uns — wir antworten an die E-Mail deines Kontos.",
  "ajuda.assuntoLabel": "Betreff",
  "ajuda.enviarComo": "Senden als %A%.",
  "ajuda.aTuaConta": "dein Konto",
  "ajuda.semContaAviso": "Schreib ungezwungen. Zum Senden brauchst du ein Konto (geht schnell) — wir speichern, was du geschrieben hast.",
  "ajuda.mensagemLabel": "Nachricht",
  "ajuda.msgPlaceholder": "Beschreibe genau: was passiert ist, auf welchem Bildschirm, und was du erwartet hast.",
  "ajuda.msgAjuda": "Je mehr Kontext du gibst (was passiert ist, wo und was du erwartet hast), desto schneller können wir dir helfen.",
