const DICIONARIOS: Record<Lingua, Dicionario> = { pt: PT, en: EN, es: ES, fr: FR, de: DE };

// ---------------------------------------------------------------------------
// QUE LÍNGUA MOSTRAR
//
// 1. A que a pessoa escolheu (guardada na conta e em cache local)
// 2. A do browser, se for uma das que temos
// 3. Português
//
// A escolha guarda-se no `user_metadata`, como os tutoriais: é uma preferência,
// sobrevive a logins e a troca de telemóvel. (O NÍVEL de subscrição é que nunca
// vem de lá.)
// ---------------------------------------------------------------------------

export function linguaDoBrowser(): Lingua {
  try {
    const bruto = (navigator.language || "pt").slice(0, 2).toLowerCase();
    // pt-BR e pt-PT partilham dicionário: as diferenças de vocabulário do jogo
    // são poucas e o judo fala a mesma língua nos dois lados.
    if (bruto === "en" || bruto === "es" || bruto === "fr" || bruto === "de" || bruto === "pt") return bruto as Lingua;
  } catch {
    /* servidor, ou browser sem navigator */
  }
  return "pt";
}

export function linguaGuardadaLocal(): Lingua | null {
  try {
    const l = localStorage.getItem(CHAVE_LOCAL);
    if (l === "pt" || l === "en" || l === "es" || l === "fr" || l === "de") return l;
  } catch {}
  return null;
}

export async function gravarLingua(l: Lingua): Promise<void> {
  try { localStorage.setItem(CHAVE_LOCAL, l); } catch {}
  try {
    const { data } = await supabase.auth.getSession();
    if (!data.session) return; // visitante: fica só a cache local
    await supabase.auth.updateUser({ data: { lingua: l } });
    // Espelha a língua na tabela `users` (coluna `lingua`): é de onde o SERVIDOR
    // a lê depressa, em lote, para mandar notificações/push na língua certa —
    // sem ter de ir ao metadata da conta um a um. Falha em silêncio: se a coluna
    // ainda não existir ou o RLS não deixar, a preferência fica no metadata na
    // mesma, e o backfill/leitura de recurso do servidor cobre o resto.
    const uid = data.session.user?.id;
    if (uid) { try { await supabase.from("users").update({ lingua: l }).eq("id", uid); } catch {} }
  } catch {}
}

async function linguaDaConta(): Promise<Lingua | null> {
  try {
    const { data } = await supabase.auth.getSession();
    const meta = data.session?.user?.user_metadata as { lingua?: string } | undefined;
    const l = meta?.lingua;
    if (l === "pt" || l === "en" || l === "es" || l === "fr" || l === "de") return l;
  } catch {}
  return null;
}

// ---------------------------------------------------------------------------

interface Contexto {
  lingua: Lingua;
  mudar: (l: Lingua) => void;
  t: (chave: string, vars?: Record<string, string | number>) => string;
}

const LinguaContexto = createContext<Contexto | null>(null);

/** Substitui {var} pelos valores dados. */
function preencher(texto: string, vars?: Record<string, string | number>): string {
  if (!vars) return texto;
  let out = texto;
  for (const [k, v] of Object.entries(vars)) out = out.split(`{${k}}`).join(String(v));
  return out;
}

export function traduzir(lingua: Lingua, chave: string, vars?: Record<string, string | number>): string {
  // Recurso ao português quando falta tradução — nunca à chave crua.
  const texto = DICIONARIOS[lingua][chave] ?? PT[chave] ?? chave;
  return preencher(texto, vars);
}

export function LinguaProvider({ children }: { children: ReactNode }) {
  // Arranca em português no servidor e no primeiro render, para o HTML do
  // servidor e o do cliente coincidirem. A língua real entra logo a seguir.
  const [lingua, setLingua] = useState<Lingua>("pt");

  useEffect(() => {
    let vivo = true;
    const local = linguaGuardadaLocal();
    if (local) setLingua(local);
    else setLingua(linguaDoBrowser());

    // A conta tem a última palavra: é o que segue a pessoa entre aparelhos.
    linguaDaConta().then((l) => {
      if (vivo && l) {
        setLingua(l);
        try { localStorage.setItem(CHAVE_LOCAL, l); } catch {}
      }
    });
    return () => { vivo = false; };
  }, []);

  function mudar(l: Lingua) {
    setLingua(l);
    void gravarLingua(l);
  }

  const valor: Contexto = {
    lingua,
    mudar,
    t: (chave, vars) => traduzir(lingua, chave, vars),
  };

  return createElement(LinguaContexto.Provider, { value: valor }, children);
}

/** O hook do dia a dia: `const t = useT();` */
export function useT(): (chave: string, vars?: Record<string, string | number>) => string {
  const ctx = useContext(LinguaContexto);
  // Sem provider (um componente isolado, um teste), devolve português em vez de
  // rebentar. Um ecrã em português é melhor do que um ecrã em branco.
  if (!ctx) return (chave, vars) => traduzir("pt", chave, vars);
  return ctx.t;
}

// ---------------------------------------------------------------------------
// DATAS E MESES — pelo browser, não à mão
//
// Havia listas de meses escritas em português espalhadas pelos ecrãs
// ("Janeiro", "Fevereiro"…). Traduzi-las seriam 12 nomes × 5 línguas, com o
// problema extra de cada língua ter as suas regras (o alemão capitaliza, o
// francês não; o inglês diz "3 March 2026", o português "3 de março de 2026").
//
// O Intl já sabe tudo isto. Mesmo princípio dos países.
// ---------------------------------------------------------------------------

/** "Março", "March", "Mars", "März". `mes` de 1 a 12. */
export function nomeDoMes(mes: number, lingua: Lingua, maiuscula = true): string {
  try {
    const d = new Date(2000, Math.max(0, Math.min(11, mes - 1)), 1);
    const nome = new Intl.DateTimeFormat(lingua, { month: "long" }).format(d);
    return maiuscula ? nome.charAt(0).toUpperCase() + nome.slice(1) : nome;
  } catch {
    return String(mes);
  }
}

/**
 * Uma data por extenso, na língua e nas convenções de cada uma.
 * Aceita "AAAA/MM/DD" (o formato do calendário) ou "AAAA-MM-DD".
 */
export function dataPorExtenso(iso: string | null | undefined, lingua: Lingua): string {
  if (!iso) return "";
  try {
    const [a, m, d] = iso.replace(/-/g, "/").split("/").map((x) => parseInt(x, 10));
    if (!a || !m || !d) return String(iso);
    return new Intl.DateTimeFormat(lingua, { day: "numeric", month: "long", year: "numeric" })
      .format(new Date(a, m - 1, d));
  } catch {
    return String(iso);
  }
}

/** Hooks para os ecrãs. */
export function useNomeDoMes(): (mes: number, maiuscula?: boolean) => string {
  const ctx = useContext(LinguaContexto);
  const lingua = ctx?.lingua ?? "pt";
  return (mes, maiuscula = true) => nomeDoMes(mes, lingua, maiuscula);
}

export function useDataPorExtenso(): (iso: string | null | undefined) => string {
  const ctx = useContext(LinguaContexto);
  const lingua = ctx?.lingua ?? "pt";
  return (iso) => dataPorExtenso(iso, lingua);
}

// ---------------------------------------------------------------------------
// AS FAIXAS
//
// O VALOR gravado em `users.belt` é sempre em português e minúsculas
// ("azul", "preta"). NUNCA muda: é a chave dos rankings por faixa, dos
// percentis mensais e das comparações. Traduzi-lo criaria contas com "Blau" e
// outras com "azul", e nada disso voltaria a bater certo.
//
// O que se traduz é o RÓTULO. Mesmo padrão dos países: o código fica, o texto
// muda. "azul" continua a ser "azul" na base, e o ecrã mostra Blue, Bleue,
// Azul ou Blau.
//
// Ao contrário do ippon ou do waza-ari, "azul" não é um termo técnico japonês —
// é uma cor, e todas as línguas a dizem à sua maneira.
// ---------------------------------------------------------------------------

const FAIXAS_VALIDAS = ["branca", "azul", "amarela", "verde", "roxa", "marrom", "preta"];

/**
 * O nome da faixa na língua pedida. Aceita qualquer valor e cai em "branca" se
 * não reconhecer — a mesma tolerância do normalizarFaixa do lib/faixas.
 *
 * Não importa o lib/faixas de propósito: esse ficheiro é usado no servidor
 * (recálculo mensal das faixas) e este é um módulo de cliente.
 */
export function nomeFaixa(valor: string | null | undefined, lingua: Lingua): string {
  const v = String(valor || "").trim().toLowerCase();
  const chave = FAIXAS_VALIDAS.includes(v) ? v : "branca";
  return traduzir(lingua, `faixa.${chave}`);
}

/** "Faixa Azul", "Blue belt", "Ceinture bleue", "Blau Gürtel". */
export function rotuloFaixa(valor: string | null | undefined, lingua: Lingua): string {
  return traduzir(lingua, "faixa.rotulo", { faixa: nomeFaixa(valor, lingua) });
}

/** Hook para os ecrãs: `const faixaEm = useNomeFaixa(); faixaEm(belt)` */
export function useNomeFaixa(): (valor: string | null | undefined) => string {
  const ctx = useContext(LinguaContexto);
  const lingua = ctx?.lingua ?? "pt";
  return (valor) => nomeFaixa(valor, lingua);
}

/** Hook para o rótulo completo. */
export function useRotuloFaixa(): (valor: string | null | undefined) => string {
  const ctx = useContext(LinguaContexto);
  const lingua = ctx?.lingua ?? "pt";
  return (valor) => rotuloFaixa(valor, lingua);
}

/** Para o seletor de idioma no perfil. */
export function useLingua(): { lingua: Lingua; mudar: (l: Lingua) => void } {
  const ctx = useContext(LinguaContexto);
  if (!ctx) return { lingua: "pt", mudar: () => {} };
  return { lingua: ctx.lingua, mudar: ctx.mudar };
}
